        val = val.item()

    elif isinstance(val, str):
        dtype = np.object_

    elif isinstance(val, (np.datetime64, datetime)):
        val = tslibs.Timestamp(val)
        if val is tslibs.NaT or val.tz is None:
            dtype = np.dtype("M8[ns]")
        else:
            if pandas_dtype:
                dtype = DatetimeTZDtype(unit="ns", tz=val.tz)
            else:
                return np.object_, val
        val = val.value

    elif isinstance(val, (np.timedelta64, timedelta)):
        val = tslibs.Timedelta(val).value
        dtype = np.dtype("m8[ns]")

    elif is_bool(val):
        dtype = np.bool_

    elif is_integer(val):
        if isinstance(val, np.integer):
            dtype = type(val)
        else:
            dtype = np.int64

    elif is_float(val):
        if isinstance(val, np.floating):
            dtype = type(val)
        else:
            dtype = np.float64

    elif is_complex(val):
        dtype = np.complex_

    elif isinstance(val, pd.Interval) and pandas_dtype:
        # New handling for Interval type
        closed = val.closed
        if is_integer(val.left) and is_integer(val.right):
            dtype = 'interval[int64]'
        elif is_float(val.left) and is_float(val.right):
            dtype = 'interval[float64]'
        elif isinstance(val.left, (Timestamp, np.datetime64)) and isinstance(val.right, (Timestamp, np.datetime64)):
            dtype = 'interval[datetime64[ns]]'
        elif isinstance(val.left, Timedelta) and isinstance(val.right, Timedelta):
            dtype = 'interval[timedelta64[ns]]'
        else:
            dtype = np.object_

    return dtype, val
